def label(a,bgv):
    lab=np.zeros_like(a,dtype=int); n=0
    H,W=a.shape
    for y in range(H):
        for x in range(W):
            if a[y,x]!=bgv and lab[y,x]==0:
                q=deque([(y,x)]); lab[y,x]=n
                while q:
                    yy,xx=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and a[ny,nx]!=bgv and lab[ny,nx]==0:
                            lab[ny,nx]=n; q.append((ny,nx))
                n+=1
    return lab,n
def solve(a,namef=None):
    H,W=a.shape; bgv=3 if namef=='4' else (7 if namef=='1' else (6 if namef=='2' else 5))
    dd=(a!=np.array(np.zeros_like(a)))
    vis=np.zeros_like(a,dtype=bool); q=deque()
    for y in range(H):
        for x in (0,W-1):
            if a[y,x]==bgv: vis[y,x]=True; q.append((y,x))
    for x in range(W):
        for y in (0,H-1):
            if a[y,x]==bgv: vis[y,x]=True; q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and a[ny,nx]==bgv and not vis[ny,nx]:
                vis[ny,nx]=True; q.append((ny,nx))
